    # @rbs marketplace: String -- A list of country codes representing Amazon marketplaces
    # @rbs recommendation_type_enum: String -- The unique identifier of the recommendation type. Used to classify and group similar recommendations (e.g. 'BRANDED_KEYWORD'). **RecommendationTypeEnum Enum:** | RecommendationTypeEnum | Description | | --- | --- | | `AUTOMATIC_GLOBAL_ADS_ENROLLMENT` | Surfaces an advertiser's automatic global ads enrollment status and trial performance. No additional type details are required when querying. |
    #: (?ad_product: String?, ?language_locale_iso: String?, ?marketplace: String?, ?recommendation_type_enum: String?, ?next_token: String?, ?max_results: Integer?) -> HTTP::Response
    def list_recommendation(ad_product: nil, language_locale_iso: nil, marketplace: nil, recommendation_type_enum: nil, next_token: nil, max_results: nil)
      request(:get, "/adsApi/v1/recommendations", params: { "adProduct" => ad_product, "languageLocaleIso" => language_locale_iso, "marketplace" => marketplace, "recommendationTypeEnum" => recommendation_type_enum, "nextToken" => next_token, "maxResults" => max_results }.compact)
    end

    # Fetch full recommendations for a given advertiser and product.
    #: (access_requested_accounts: Array[untyped], ?ad_product_filter: untyped?, ?language_filter: untyped?, ?marketplaces_filter: untyped?, ?max_results: Integer?, ?next_token: String?, ?recommendation_type_details_filter: untyped?, ?recommendation_type_filter: untyped?) -> HTTP::Response
    def query_recommendation(access_requested_accounts:, ad_product_filter: nil, language_filter: nil, marketplaces_filter: nil, max_results: nil, next_token: nil, recommendation_type_details_filter: nil, recommendation_type_filter: nil)
      request(:post, "/adsApi/v1/query/recommendations", json: { "accessRequestedAccounts" => access_requested_accounts, "adProductFilter" => ad_product_filter, "languageFilter" => language_filter, "marketplacesFilter" => marketplaces_filter, "maxResults" => max_results, "nextToken" => next_token, "recommendationTypeDetailsFilter" => recommendation_type_details_filter, "recommendationTypeFilter" => recommendation_type_filter }.compact)
    end

    # Create recommendations
    #: (?recommendations: Array[untyped]?) -> HTTP::Response
    def sb_create_recommendation(recommendations: nil)
      request(:post, "/adsApi/v1/create/recommendations/sb", json: { "recommendations" => recommendations }.compact)
    end
  end
